// Polish texts of catalog.mjs: [English text, Polish text], in catalog order. The English side must match the T() text
// exactly (the build names any text without a translation and any entry whose English text changed or went away).
// Terms follow the app (src/Filee.App/Assets/i18n/pl.json): ustawienie wstępne (preset), silnik (engine), pasek-pierścień
// (donut toolbar), obserwowane foldery (watch folders), strefa upuszczania (drop zone), preset names as in the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `wideo i audio, wyodrębnianie napisów i zapis do HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `starsze formaty biurowe, takie jak DOC, PPT i ODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `rzadkie formaty e-booków i zapis do MOBI/AZW3`],
  [`EPS and PostScript`,
    `EPS i PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc i inne języki znaczników, Word → Markdown oraz Markdown → slajdy`],

  // Options
  [`quality`, `jakość`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Regulowana jakość JPG, WEBP i AVIF: JPG zapisuje się domyślnie z jakością 90%, a ustawienie wstępne JPG 70% daje mniejsze pliki.`],
  [`resize`, `zmiana rozmiaru`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Zmiana rozmiaru podczas konwersji: procentowo (np. o połowę) lub do maksymalnej długości dłuższego boku.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Ustawienie DPI zapisywanego w obrazie, np. 300 do druku.`],
  [`grayscale`, `skala szarości`],
  [`A grayscale preset makes black-and-white copies.`,
    `Ustawienie wstępne Skala szarości tworzy czarno-białe kopie.`],
  [`metadata`, `metadane`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Metadane (EXIF, XMP, profil kolorów) są domyślnie zachowywane i można je usunąć dla ochrony prywatności.`],
  [`ICO sizes`, `rozmiary ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Pliki ICO zawierają domyślnie rozmiary 256, 128, 64, 48, 32 i 16 px; można je zmienić w ustawieniu wstępnym.`],
  [`TIFF compression`, `kompresja TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `Można wybrać kompresję TIFF (domyślnie LZW).`],
  [`white background`, `białe tło`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG nie obsługuje przezroczystości, więc przezroczyste obszary są wypełniane bielą.`],
  [`merge into one PDF`, `łączenie w jeden PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Ustawienie wstępne Połącz PDF łączy wszystkie upuszczone pliki w jeden PDF.`],
  [`split pages`, `dzielenie na strony`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Ustawienie wstępne Podziel PDF zapisuje każdą stronę jako osobny PDF w podfolderze.`],
  [`rotate & flip`, `obracanie i odbijanie`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Ustawienia wstępne Obróć i Odbij obracają obrazy w lewo, w prawo lub o 180° i odbijają je lustrzanie – po uwzględnieniu orientacji zapisanej w zdjęciu.`],
  [`Trace to SVG`, `wektoryzacja do SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Dwa ustawienia wstępne zamieniają obraz na kształty wektorowe: Wektoryzuj do SVG w maksymalnie 64 kolorach i Rysunek do SVG w czerni – do logo, podpisów i skanów. Żaden inny program nie jest potrzebny.`],
  [`remove background`, `usuwanie tła`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Ustawienie wstępne Usuń tło sprawia, że jednolite tło staje się przezroczyste: papier za podpisem lub pieczątką albo tło logo.`],
  [`page ranges`, `zakresy stron`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Zakresy stron, np. 1-3,5, ograniczają konwersję do potrzebnych stron.`],
  [`render DPI`, `DPI renderowania`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Strony są domyślnie renderowane w 150 DPI; do druku wybierz 300 DPI.`],
  [`one long image`, `jeden długi obraz`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Ustawienie wstępne Długi obraz układa wszystkie strony jedna pod drugą w jednym wysokim obrazie, np. by opublikować cały dokument naraz.`],
  [`compress PDF`, `kompresja PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `Ustawienie wstępne Kompresuj PDF zmniejsza plik, który pozostaje PDF-em: obrazy są pomniejszane do 72, 150 lub 300 dpi, a zdjęcia zapisywane ponownie jako JPEG, natomiast tekst, czcionki, linki, zakładki i formularze zostają bez zmian. PDF, którego nie da się zmniejszyć, pozostaje taki, jaki był. Jeśli zainstalowano Ghostscript, Filee może spróbować także nim i zachować mniejszy wynik.`],
  [`a picture per slide`, `obraz strony na slajdzie`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (slajdy) umieszcza obraz każdej strony na osobnym slajdzie w rozmiarze strony, a tekst strony w notatkach prelegenta. Slajdy wyglądają dokładnie jak PDF, ale nie da się ich edytować; aby edytować tekst, konwertuj do DOCX.`],
  [`vector PDF`, `wektorowy PDF`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `PDF pozostaje wektorowy, więc jest ostry przy każdym powiększeniu i w druku.`],
  [`editable`, `edytowalny`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Wynik zawiera prawdziwy tekst i akapity, które można edytować, a nie obrazy stron.`],
  [`attachments as ZIP`, `załączniki jako ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `Załączniki można zapisać osobno jako jeden plik ZIP.`],
  [`one CSV per sheet`, `jeden CSV na arkusz`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Skoroszyty z kilkoma arkuszami dają jeden plik CSV na arkusz.`],
  [`layout kept`, `zachowany układ`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Zachowuje rozmiar strony i marginesy, nagłówki i stopki z numerami stron, tabele, pola tekstowe, kształty i obrazy.`],
  [`no Office needed`, `bez Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `Microsoft Office ani LibreOffice nie są potrzebne.`],
  [`no Hancom Office needed`, `bez Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `Bez Hancom Office i bez okna zatwierdzania.`],
  [`no AutoCAD needed`, `bez AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`,
    `AutoCAD ani przeglądarka DWG nie są potrzebne.`],
  [`no re-encoding`, `bez ponownego kodowania`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Gdy nowy format może przyjąć obraz i dźwięk bez zmian (MOV z iPhone’a → MP4), są one tylko przepakowywane: bez utraty jakości, z zachowaniem HDR, w kilka sekund.`],
  [`720p option`, `opcja 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `Ustawienie wstępne MP4 720p zmniejsza duże filmy do udostępniania.`],
  [`extract audio`, `wyodrębnianie dźwięku`],
  [`Only the sound is saved, without the video track.`,
    `Zapisywany jest tylko dźwięk, bez ścieżki wideo.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `Ustawienie wstępne MP3 128k daje mniejsze pliki, idealne do nagrań mowy.`],
  [`extract`, `rozpakowywanie`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Ustawienie wstępne Rozpakuj wypakowuje zamiast tego archiwum do folderu.`],
  [`pack into one ZIP`, `pakowanie w jeden ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `Dowolnie zaznaczone pliki można spakować w jeden ZIP.`],
  [`DRM-free books`, `książki bez DRM`],
  [`Works with DRM-free books only.`,
    `Działa tylko z książkami bez DRM.`],
  [`ALAC in M4A`, `ALAC w M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `M4A może zawierać nie tylko AAC, ale też bezstratny ALAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Ustawienia wstępne wideo mogą kodować do HEVC (H.265) lub AV1, co daje mniejsze pliki z zachowaniem 10-bitowego obrazu i HDR.`],
  [`hardware encoding`, `kodowanie sprzętowe`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Włącz „Użyj akceleracji sprzętowej” w ustawieniu wstępnym wideo, aby kodować H.264 i HEVC na karcie graficznej (NVENC, Quick Sync, AMF, VideoToolbox lub VA-API): znacznie szybciej i oszczędniej, choć przy tej samej jakości plik jest nieco większy. Domyślnie opcja jest wyłączona, a bez obsługiwanej karty wideo jest kodowane jak dotąd.`],
  [`every frame`, `każda klatka`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Zwykle z filmu powstaje jedna nieruchoma klatka. Ustawienia wstępne Wyodrębnij klatki albo opcja „Zapisz każdą klatkę wideo” w ustawieniu PNG lub JPG zapisują każdą klatkę (lub co N-tą) jako obrazy w folderze obok filmu.`],
  [`extract subtitles`, `wyodrębnianie napisów`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Ustawienie wstępne Wyodrębnij napisy na pierścieniu wideo zapisuje pierwszą tekstową ścieżkę napisów filmu jako SRT.`],
  [`saved as UTF-8`, `zapis w UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Wyniki są zapisywane w UTF-8. Koreańskie pliki zapisane w CP949 (EUC-KR) są rozpoznawane i poprawnie odczytywane.`],
  [`tables to CSV / Excel`, `tabele do CSV / Excela`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Dane w postaci tabeli (listy rekordów) można też konwertować do i z CSV oraz Excela.`],
  [`picture preview`, `podgląd jako obraz`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG lub JPG daje cieniowany obraz modelu widzianego z przodu, z prawej strony i z góry.`],
  [`colours and textures`, `kolory i tekstury`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Kolory, tekstury i materiały są zachowywane, jeśli format docelowy je obsługuje. STL zapisuje tylko kształt.`],
  [`HDR tone-mapped`, `mapowanie tonów HDR`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Zrzuty ekranu HDR, które Windows zapisuje jako JPEG XR, są sprowadzane do zwykłej jasności przez mapowanie tonów, a nie przycinane w jasnych partiach.`],
  [`Live Photo video`, `wideo z Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Ustawienie wstępne „Wyodrębnij wideo z Live Photo” zapisuje jako MP4 lub MOV wideo z Live Photo z iPhone’a (pliku LIVP z iCloud albo zdjęcia razem z jego plikiem MOV) lub z Motion Photo z Androida. W drugą stronę ustawienia wstępne „Live Photo (iPhone)” i „Motion Photo (Android)” zamieniają krótki fragment wideo w ruchome zdjęcie; ta funkcja jest jeszcze eksperymentalna.`],
  [`WGS 84 longitude / latitude`, `długość / szerokość geograficzna WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Wyniki zawsze mają współrzędne w postaci długości i szerokości geograficznej (WGS 84). Pliki Shapefile w układach UTM, Web Mercator, Lambert lub Albers są przeliczane, więc otwierają się we właściwym miejscu; konwersja pliku do tego samego formatu przelicza jego współrzędne.`],
  [`save as ZIP`, `zapis jako ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Shapefile to pięć plików (.shp, .shx, .dbf, .prj i .cpg). Z opcją „Zapisz wynik jako ZIP” w ustawieniu wstępnym albo „Zapisuj każdy wynik geoprzestrzenny jako ZIP” w Ustawienia → Ogólne trafiają razem do jednego pliku ZIP.`],

  // Text that needs shaping
  [`DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX with text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) go to PDF and images through the optional LibreOffice engine`,
    `DOCX, TXT, Markdown, HTML, XLSX, PPTX i HWPX z tekstem wymagającym kształtowania (arabski, hebrajski, pisma indyjskie, tajski i inne) trafiają do PDF i obrazów przez opcjonalny silnik LibreOffice`],
  [`Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Wyjątkiem jest tekst wymagający kształtowania (arabski, hebrajski, pisma indyjskie, tajski i inne): pliki DOCX, TXT, Markdown, HTML, XLSX, PPTX i HWPX z takim tekstem trafiają do PDF i obrazów przez opcjonalny silnik LibreOffice. Bez LibreOffice konwersja takiego pliku kończy się komunikatem podającym nazwę pisma, zamiast dawać uszkodzony plik PDF.`],

  // Camera RAW
  [`Canon CR2 RAW photo`, `Zdjęcie RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 to format zdjęć RAW, którego lustrzanki Canon używały przez wiele lat (nowsze modele zapisują CR3). Przechowuje nieprzetworzone dane z matrycy, co daje duże pole do obróbki.`],
  [`Nikon NEF RAW photo`, `Zdjęcie RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF to format zdjęć RAW Nikona, używany przez lustrzanki Nikon i bezlusterkowce serii Z. Jak inne pliki RAW zawiera nieprzetworzone dane z matrycy i jest kilka razy większy niż JPG.`],

  // Images
  [`Images`, `Obrazy`],
  [`images`, `obrazy`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Zdjęcia i grafika, w tym HEIC i Live Photo z iPhone’a, PSD z Photoshopa, RAW z aparatów wszystkich głównych marek, animowany APNG, DICOM oraz zrzuty ekranu HDR z Windows (JPEG XR). Podczas konwersji możesz zmienić rozmiar, obrócić obraz, ustawić jakość i DPI lub usunąć metadane, a także zamienić obraz na wektorowy SVG.`],
  [`JPEG image`, `Obraz JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG to najpopularniejszy format zdjęć. Kompresja stratna sprawia, że pliki są małe, ale każdy zapis w niższej jakości usuwa część szczegółów, a przezroczystość nie jest obsługiwana.`],
  [`PNG image`, `Obraz PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG to bezstratny format obrazów z przezroczystością, idealny do zrzutów ekranu, logo i grafik o ostrych krawędziach. Zdjęcia zapisane jako PNG są zwykle znacznie większe niż JPG.`],
  [`WebP image`, `Obraz WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP to format obrazów Google przeznaczony do sieci. Obsługuje kompresję stratną i bezstratną oraz przezroczystość i zwykle jest mniejszy niż JPG czy PNG, ale niektóre edytory i formularze przesyłania wciąż go nie akceptują.`],
  [`AVIF image`, `Obraz AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF to nowoczesny format obrazów oparty na kodeku wideo AV1. Kompresuje lepiej niż JPG i WebP, ale starsze programy i urządzenia wciąż słabo go obsługują.`],
  [`HEIC / HEIF image`, `Obraz HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) to domyślny format zdjęć w iPhone’ach i iPadach. Zdjęcia zajmują często około połowy miejsca potrzebnego dla JPG, ale wiele aplikacji Windows, stron internetowych i starszych urządzeń nie potrafi ich otworzyć.`],
  [`GIF image / animation`, `Obraz / animacja GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF to stary format obrazów ograniczony do 256 kolorów, który obsługuje prostą animację. Wciąż jest uniwersalnym sposobem na udostępnianie krótkich, niemych pętli w czatach, dokumentach i zgłoszeniach błędów.`],
  [`Windows icon`, `Ikona Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO to format ikon Windows. Jeden plik ICO zawiera ten sam obraz w kilku rozmiarach (np. 16, 32, 48 i 256 pikseli), więc wygląda ostro wszędzie – od paska zadań po favikony stron internetowych.`],
  [`Photoshop document`, `Dokument Photoshopa`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD to natywny format Adobe Photoshopa. Zachowuje warstwy, maski i ustawienia korekt, więc świetnie nadaje się do edycji, ale większość przeglądarek obrazów i stron internetowych go nie otworzy.`],
  [`macOS icon`, `Ikona macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS to format ikon systemu macOS. Podobnie jak ICO łączy kilka rozmiarów jednego obrazu, aż do 1024×1024 dla ekranów Retina, i służy do ikon aplikacji na Macu.`],
  [`Camera RAW`, `RAW z aparatu`],
  [`Windows only`, `tylko w Windows`],
  [`the photo of the Live Photo`, `zdjęcie z Live Photo`],
  [`the video of the Live Photo`, `wideo z Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Grafika wektorowa`],
  [`vector graphics`, `grafika wektorowa`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, metapliki Windows, Illustrator, EPS/PostScript oraz rysunki z CorelDRAW, Visio i LibreOffice Draw. SVG można też zamienić na DXF lub DWG do programów CAD.`],
  [`SVG vector graphic`, `Grafika wektorowa SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG to oparty na XML format grafiki wektorowej. Kształty i tekst pozostają ostre w każdym rozmiarze, dlatego idealnie nadaje się do logo i ikon w sieci, ale wiele aplikacji i formularzy przesyłania przyjmuje tylko obrazy rastrowe.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS to format wektorowy z branży poligraficznej i projektowej, często używany do logo i ilustracji wysyłanych do drukarni. Większość nowoczesnych aplikacji nie wyświetli go bez interpretera PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `pliki AI zapisane z zawartością PDF (domyślnie w Illustratorze)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Zamieniaj PDF na obrazy, edytowalne dokumenty Word lub HWPX, slajdy PowerPoint, tekst albo archiwum komiksu oraz łącz, dziel, kompresuj i wybieraj strony.`],
  [`PDF document`, `Dokument PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF to standard udostępniania dokumentów, które muszą wszędzie wyglądać tak samo. Czcionki, układ i obrazy są stałe, a plik otworzy się na każdym urządzeniu. Z tego samego powodu PDF trudno edytować.`],
  [`one page`, `jedna strona`],

  // Documents
  [`Documents`, `Dokumenty`],
  [`documents`, `dokumenty`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Dokumenty Word bez Microsoft Office, chińskie e-faktury OFD, starsze i rzadkie formaty edytorów tekstu z opcjonalnym silnikiem LibreOffice oraz zapisane e-maile (EML i Outlook MSG).`],
  [`Word document`, `Dokument Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX to format Microsoft Word od wersji Word 2007 (Office Open XML). To najpopularniejszy format edytowalnych dokumentów, takich jak raporty, listy i formularze.`],
  [`Word 97–2003 document`, `Dokument Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC to binarny format Worda 97–2003. Wciąż pojawia się w starych archiwach, urzędowych formularzach i dawnych systemach, ale jest zastępowany przez DOCX.`],
  [`E-mail message`, `Wiadomość e-mail`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML to pojedynczy e-mail zapisany jako plik (format MIME) z nagłówkami, treścią i załącznikami. Otworzy go większość programów pocztowych, w tym Outlook i Thunderbird.`],
  [`Outlook message`, `Wiadomość Outlooka`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG to plik, który Microsoft Outlook zapisuje, gdy przeciągniesz z niego wiadomość. Otwiera go tylko Outlook, więc trudno go przeczytać na komputerze bez Outlooka lub na telefonie.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `koreańskie HWP/HWPX`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Koreańskie dokumenty Hancom Hangul bez Hancom Office: HWP ↔ HWPX, do PDF, obrazów, Worda, tekstu, Markdown i HTML, a także HWPX z Worda, Excela, PowerPointa, Markdown i PDF.`],
  [`Hangul document (HWP)`, `Dokument Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP to format dokumentów Hancom Office Hangul (한글) – standardowego edytora tekstu w koreańskich urzędach, szkołach i wielu firmach. Poza Koreą niewiele programów potrafi go otworzyć.`],
  [`Hangul document (HWPX)`, `Dokument Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX to otwarty, oparty na XML format Hancom Hangul (OWPML, koreańska norma krajowa KS X 6101). Koreańskie instytucje publiczne przechodzą na niego z binarnego formatu HWP.`],

  // Spreadsheets
  [`Spreadsheets`, `Arkusze kalkulacyjne`],
  [`spreadsheets`, `arkusze kalkulacyjne`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Arkusze Excel, OpenDocument i CSV/TSV – do PDF z dopasowaniem do strony jak w Excelu lub między sobą, bez Excela.`],
  [`Excel workbook`, `Skoroszyt Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX to format skoroszytów Microsoft Excel od wersji Excel 2007. Jeden skoroszyt może zawierać kilka arkuszy z formułami, formatowaniem, wykresami i obrazami.`],
  [`Excel 97–2003 workbook`, `Skoroszyt Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS to binarny format skoroszytów Excela 97–2003. Wciąż tworzy go wiele starszych systemów oraz eksporty z banków i programów księgowych.`],
  [`Comma-separated values`, `Wartości rozdzielane przecinkami`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV to zwykły tekst z jednym wierszem tabeli w każdej linii. Odczyta go każdy arkusz kalkulacyjny, baza danych i język programowania, ale nie ma w nim formatowania, formuł ani wielu arkuszy.`],

  // Presentations
  [`Presentations`, `Prezentacje`],
  [`presentations`, `prezentacje`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint do PDF, obrazów i HWPX bez PowerPointa; starsze PPT, ODP i Keynote z opcjonalnym silnikiem LibreOffice.`],
  [`PowerPoint presentation`, `Prezentacja PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX to format Microsoft PowerPoint od wersji PowerPoint 2007. Zawiera slajdy z tekstem, obrazami, kształtami, tabelami, notatkami i animacjami.`],
  [`PowerPoint 97–2003 presentation`, `Prezentacja PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT to binarny format PowerPointa 97–2003. Stare materiały z wykładów i archiwalne prezentacje często wciąż są w PPT.`],

  // Text & markup
  [`Text & markup`, `Tekst i znaczniki`],
  [`text and markup`, `tekst i znaczniki`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Zwykły tekst, Markdown, HTML i zapisane strony internetowe (MHTML) do PDF, Worda, HWPX i EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter i inne języki znaczników korzystają z opcjonalnego silnika Pandoc, który zamienia też Markdown na slajdy PowerPoint.`],
  [`Plain text`, `Zwykły tekst`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT to zwykły tekst bez żadnego formatowania – najprostszy i najbardziej przenośny format dokumentów. Różnić może się jedynie kodowanie znaków (UTF-8, UTF-16 lub dawna strona kodowa).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown to lekki język znaczników w zwykłym tekście: # oznacza nagłówki, * listy, ** pogrubienie. Jest popularny w notatkach, plikach README i dokumentacji, a czyta się go wygodnie nawet bez renderowania.`],
  [`Web page (HTML)`, `Strona internetowa (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML to język stron internetowych. Zapisany plik .html otworzy każda przeglądarka, ale jego wygląd zależy od przeglądarki oraz podlinkowanych stylów i obrazów, których offline może brakować.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `pliki LOG i skrypty (PY, PAC, BAT, COMMAND) są odczytywane jako tekst i nigdy nie są uruchamiane`],
  [`the saved page, with its pictures`, `zapisana strona razem z obrazami`],

  // Data
  [`Data`, `Dane`],
  [`data files`, `pliki danych`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML i XML między sobą, a tabele do i z CSV oraz Excela. Kontakty vCard do i z CSV, także ze starych telefonów. Nic nie trzeba instalować.`],
  [`JSON data`, `Dane JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON to format danych sieci: obiekty, listy, tekst i liczby zapisane zwykłym tekstem. Używają go wszędzie API, aplikacje i pliki ustawień.`],
  [`YAML data`, `Dane YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML przechowuje te same dane co JSON, ale zapisane wcięciami zamiast nawiasów. Pliki konfiguracyjne Dockera, Kubernetesa, potoków CI i wielu aplikacji to YAML.`],
  [`vCard contacts`, `Kontakty vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) to standardowy plik z kontaktami. Telefony, Outlook, Kontakty Google i iCloud eksportują książki adresowe jako vCard, często z wieloma kontaktami w jednym pliku.`],

  // E-books & comics
  [`E-books & comics`, `E-booki i komiksy`],
  [`e-books and comics`, `e-booki i komiksy`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook i archiwa komiksów (CBZ, CBR, CB7…) do PDF, EPUB, Worda i innych formatów, a także KEPUB dla czytników Kobo. Tylko książki bez DRM.`],
  [`EPUB e-book`, `E-book EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB to otwarty standard e-booków. Tekst dopasowuje się do każdego ekranu, a obsługuje go większość czytników i aplikacji do czytania; Kindle przyjmuje EPUB przez Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `E-book Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI to starszy format e-booków Mobipocket, którego Amazon Kindle używał przez lata. Wciąż jest częsty w starszych kolekcjach e-booków, ale Amazon przeszedł na AZW3/KFX i EPUB.`],

  // Video
  [`Video`, `Wideo`],
  [`video`, `wideo`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Wszystkie popularne formaty wideo do MP4 (H.264, HEVC lub AV1), WebM, MOV, MKV, AVI, GIF lub APNG – z opcją 720p, kodowaniem sprzętowym na karcie graficznej, wyodrębnianiem dźwięku do MP3 lub M4A i zapisem każdej klatki jako obrazu. Korzysta z opcjonalnego silnika FFmpeg.`],
  [`MPEG-4 video`, `Wideo MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) to najbardziej uniwersalny format wideo. Odtwarzają go telefony, telewizory, przeglądarki i każdy serwis wideo; zwykle zawiera obraz H.264 lub H.265 i dźwięk AAC.`],
  [`QuickTime movie`, `Film QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV to format wideo QuickTime firmy Apple, używany przez iPhone’y i Maki. Zwykle zawiera obraz H.264 lub HEVC, ale niektóre edytory, telewizory i strony internetowe lepiej radzą sobie z MP4.`],
  [`Matroska video`, `Wideo Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) to elastyczny, otwarty kontener, który może zawierać wiele ścieżek wideo, audio i napisów. Jest popularny w filmach i nagraniach, ale telefony, telewizory i edytory nie zawsze go odtwarzają.`],
  [`WebM video`, `Wideo WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM to otwarty format wideo stworzony dla przeglądarek (obraz VP8/VP9 lub AV1 z dźwiękiem Vorbis lub Opus). Nagrania ekranu i pobrane filmy to często WebM, ale wiele edytorów i urządzeń oczekuje MP4.`],
  [`AVI video`, `Wideo AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI to kontener wideo Microsoftu z lat 90. Na kamerach, starszych aparatach i w archiwach wciąż są pliki AVI, które często są duże i słabo obsługiwane przez telefony.`],
  [`one still frame or every frame`, `jedna nieruchoma klatka lub każda klatka`],

  // Audio
  [`Audio`, `Audio`],
  [`audio`, `audio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Muzyka, nagrania i notatki głosowe do MP3, M4A, WAV, FLAC, OGG, Opus, AAC lub bezstratnych WavPack i TTA. Odczytuje też APE, DSD i DTS. Korzysta z opcjonalnego silnika FFmpeg.`],
  [`MP3 audio`, `Audio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 to klasyczny format skompresowanego dźwięku. Odtwarza go praktycznie każdy odtwarzacz, radio samochodowe i telefon, dlatego to najbezpieczniejszy wybór do udostępniania muzyki, podcastów i nagrań.`],
  [`MPEG-4 audio`, `Audio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A to plik audio MPEG-4, zwykle w AAC, używany przez iTunes, notatki głosowe w iPhonie i wiele dyktafonów. Brzmi dobrze przy małym rozmiarze, ale niektóre odtwarzacze i radia samochodowe przyjmują tylko MP3.`],
  [`WAV audio`, `Audio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV to nieskompresowany dźwięk (zwykle PCM) używany do nagrywania i edycji. Brzmi dokładnie jak źródło, ale w jakości CD zajmuje około 10 MB na minutę.`],
  [`FLAC lossless audio`, `Bezstratny dźwięk FLAC`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC to bezstratnie skompresowany dźwięk: pliki są mniej więcej o połowę mniejsze niż WAV bez żadnej utraty jakości, dlatego to ulubiony format bibliotek muzycznych i nagrań hi-res.`],

  // Subtitles
  [`Subtitles`, `Napisy`],
  [`subtitles`, `napisy`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML i MicroDVD między sobą bez żadnego silnika, z zapisem w UTF-8; odczytuje też SSA i SCC. Koreańskie pliki SMI i SRT w CP949 są odczytywane poprawnie. Napisy z filmu wyodrębnia FFmpeg.`],
  [`SubRip subtitles`, `Napisy SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) to najpopularniejszy plik napisów: numerowane kwestie z czasem początku i końca oraz zwykłym tekstem. Przyjmuje go niemal każdy odtwarzacz, edytor i serwis wideo.`],
  [`Advanced SubStation Alpha subtitles`, `Napisy Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) to format stylizowanych napisów, z którego korzystają fansuby anime i Aegisub – z czcionkami, kolorami, pozycjami i efektami. Wiele urządzeń i serwisów przyjmuje tylko zwykłe SRT.`],
  [`WebVTT subtitles`, `Napisy WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) to format napisów dla wideo HTML5. Używają go odtwarzacze internetowe, YouTube i platformy kursów online.`],
  [`SAMI subtitles (SMI)`, `Napisy SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) to podobny do HTML format napisów Microsoftu. W Korei to wciąż klasyczny plik napisów, często zapisany w starym kodowaniu CP949, które nowsze odtwarzacze wyświetlają jako krzaki.`],

  // Archives
  [`Archives`, `Archiwa`],
  [`archives`, `archiwa`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Przepakowuj lub rozpakowuj ZIP, 7Z, RAR, TAR, obrazy dysków i wiele innych formatów archiwów za pomocą dołączonego silnika 7-Zip albo pakuj dowolne pliki w jeden ZIP.`],
  [`ZIP archive`, `Archiwum ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP to uniwersalny format archiwów. Windows, macOS, telefony i niemal każdy formularz przesyłania otwierają go bez dodatkowych programów.`],
  [`7-Zip archive`, `Archiwum 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z to otwarty format archiwów 7-Zip. Kompresja LZMA2 daje zwykle mniejsze pliki niż ZIP, ale nie każdy system czy strona internetowa potrafi go otworzyć.`],
  [`RAR archive`, `Archiwum RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR to zastrzeżony format archiwów programu WinRAR, częsty przy pobieranych plikach podzielonych na części. Nowsze wersje Windows 11 potrafią otworzyć RAR, ale nie umieją go utworzyć, a wiele narzędzi przyjmuje tylko ZIP.`],
  [`Any files`, `Dowolne pliki`],

  // CAD drawings
  [`CAD drawings`, `Rysunki CAD`],
  [`CAD drawings [in running text]`, `rysunki CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `AutoCAD DWG i DXF: konwersja między nimi lub do PDF, SVG i PNG bez programu AutoCAD.`],
  [`AutoCAD drawing`, `Rysunek AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG to natywny format rysunków programu AutoCAD i najpopularniejszy plik CAD w architekturze i inżynierii. Bez AutoCAD lub przeglądarki DWG trudno go otworzyć czy komuś przekazać.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) to format wymiany rysunków CAD firmy Autodesk. Odczytują go wycinarki laserowe, oprogramowanie CNC i większość programów CAD, dlatego zwykle służy do przenoszenia rysunków między narzędziami.`],

  // 3D models
  [`3D models`, `Modele 3D`],
  [`3D models [in running text]`, `modele 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF i PLY między sobą, a FBX do każdego z nich – z kolorami, teksturami i materiałami, jeśli format je obsługuje – oraz do cieniowanego obrazu PNG lub JPG. Nic nie trzeba instalować.`],
  [`glTF binary (GLB)`, `Binarny glTF (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB to jednoplikowa wersja glTF – formatu 3D dla sieci, AR i silników gier. Siatki, materiały i tekstury są spakowane w jeden zwarty plik.`],
  [`STL 3D model`, `Model 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL to klasyczny plik do druku 3D. Przechowuje tylko trójkąty tworzące kształt, bez kolorów i jednostek, a odczyta go każdy slicer i program CAD.`],
  [`Wavefront OBJ model`, `Model Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) to tekstowy format 3D, który otworzy niemal każdy program 3D. Materiały i tekstury leżą obok, w pliku .mtl i obrazach.`],

  // Fonts
  [`Fonts`, `Czcionki`],
  [`fonts`, `czcionki`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Czcionki komputerowe i internetowe: TTF, OTF, WOFF, WOFF2 i EOT między sobą.`],
  [`TrueType font`, `Czcionka TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) to najpopularniejszy format czcionek komputerowych w Windows i macOS. Po zainstalowaniu czcionki można jej używać w każdej aplikacji.`],
  [`OpenType font`, `Czcionka OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) to format czcionek opracowany przez Adobe i Microsoft. Czcionki OpenType z konturami PostScript (CFF) są częste wśród profesjonalnych krojów i obsługują funkcje takie jak ligatury.`],
  [`Web font (WOFF2)`, `Czcionka internetowa (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 to skompresowany format czcionek internetowych obsługiwany przez wszystkie nowoczesne przeglądarki. Jest zwykle o około 30% mniejszy niż WOFF, więc strony ładują się szybciej.`],

  // Geospatial data
  [`Geospatial data`, `Dane geoprzestrzenne`],
  [`geospatial data`, `dane geoprzestrzenne`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Mapy i dane GPS: GeoJSON, KML, KMZ, GPX i Shapefile między sobą oraz do CSV, Excela i JSON, a CSV ze współrzędnymi z powrotem do pliku mapy. Tylko dane wektorowe (punkty, linie i obszary), zawsze zapisywane jako długość i szerokość geograficzna. Nic nie trzeba instalować.`],
  [`one row per feature, with its coordinates`, `jeden wiersz na obiekt, z jego współrzędnymi`],
  [`a CSV with longitude and latitude columns or WKT`,
    `CSV z kolumnami długości i szerokości geograficznej lub WKT`],

  // Camera RAW group (conversion pages)
  [`Camera RAW photo`, `Zdjęcie RAW z aparatu`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Pliki RAW z aparatów (CR2, CR3, NEF, ARW, DNG, RAF, ORF i inne) zawierają nieprzetworzone dane z matrycy. Zachowują najwięcej szczegółów do obróbki, ale są duże i do ich obejrzenia potrzebny jest specjalny program.`],

  // Conversion guides: images
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG to bezpieczny wybór, gdy Twoje zdjęcia trafią na stronę internetową, do starszej aplikacji Windows albo do kogoś bez iPhone’a. Całą serię zdjęć HEIC przekonwertujesz za jednym razem, a każdy JPG zapisze się obok oryginału.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Wybierz PNG, jeśli chcesz dalej edytować zdjęcie bez kolejnej rundy kompresji JPG. PNG jest bezstratny, więc pliki będą kilka razy większe niż oryginalny HEIC.`],
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC przechowuje zdjęcie w mniej więcej połowie miejsca potrzebnego dla JPG przy tej samej jakości – tak zapisują zdjęcia iPhone’y. Zapis do HEIC wymaga darmowego silnika FFmpeg (ok. 100 MB, pobieranego raz w aplikacji). EXIF, profil kolorów i orientacja zostają zachowane.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Obrazy zapisane ze stron internetowych to często WebP. Konwersja do PNG zachowuje pełną jakość i przezroczystość, więc wynik zadziała w każdym edytorze, prezentacji i dokumencie.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Wybierz JPG, gdy obraz jest zdjęciem i liczy się rozmiar pliku, np. w formularzach przesyłania, które odrzucają WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Zrzuty ekranu i wyeksportowane zdjęcia zapisane jako PNG potrafią zajmować wiele megabajtów. Zdjęcia jako JPG są zwykle dużo mniejsze; przy zrzutach ekranu z dużą ilością tekstu i przy logo PNG często pozostaje lepszym formatem.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Konwersja JPG do PNG nie przywróci szczegółów utraconych przez kompresję JPG, ale zatrzyma dalsze straty: każda kolejna edycja i zapis będą bezstratne. Konwertuj, zanim zaczniesz retuszować obraz lub dodawać przezroczystość w edytorze.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Obrazy AVIF z nowoczesnych stron i telefonów nie otwierają się w wielu starszych programach, przeglądarkach obrazów i formularzach przesyłania. JPG otworzy się wszędzie, kosztem nieco większych plików.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP idealnie nadaje się na strony internetowe: zdjęcia są dużo mniejsze niż w JPG, a grafiki zachowują przezroczystość. Ustawienie wstępne WEBP zapisuje z jakością 85 – to dobry kompromis dla sieci.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Skany, paragony i zdjęcia dokumentów często trzeba wysłać jako jeden PDF. Upuść obrazy na ustawienie Połącz PDF, aby dostać jeden plik, albo na PDF, aby dostać osobny PDF dla każdego obrazu. Domyślnie każda strona ma rozmiar swojego obrazu.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Jeden plik ICO wystarczy na wszystkie ikony Windows – na pulpicie, w Eksploratorze i na pasku zadań – i sprawdzi się też jako favikona strony. Aby uzyskać najostrzejszy wynik, zacznij od kwadratowego PNG o wymiarach co najmniej 256×256 px.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Stworzenie ikony aplikacji na Maca w Windows zwykle wymaga dodatkowych narzędzi; Filee zamienia PNG w plik ICNS bezpośrednio. Użyj kwadratowego PNG 1024×1024 px, aby rozmiary Retina pozostały ostre.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Pokaż projekt z Photoshopa osobom, które go nie mają: PNG przedstawia obraz tak, jak został zapisany, z połączonymi widocznymi warstwami i zachowaną przezroczystością. PNG nie przechowuje warstw, więc do edycji zachowaj PSD.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee odczytuje pliki RAW z aparatów Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One i innych, a następnie wywołuje je z ustawieniami domyślnymi. To szybki sposób na JPG-i do udostępnienia prosto z sesji; do twórczej obróbki najpierw użyj edytora RAW.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Upuść naraz wszystkie pliki CR2 z karty pamięci: Filee konwertuje je równolegle i zapisuje każdy JPG obok jego pliku RAW. Nowsze aparaty Canon zapisują CR3, który Filee również odczytuje.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `Pliki NEF są zbyt duże i zbyt nietypowe, by wysyłać je w tej postaci. Jako JPG stają się małymi zdjęciami, które każdy obejrzy; do komunikatorów użyj ustawienia JPG 70% lub Połowa rozmiaru. Pliki NRW z aparatów Nikon Coolpix konwertują się tak samo.`],

  // Conversion guides: vector
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Wiele aplikacji, prezentacji i formularzy przesyłania nie przyjmuje SVG. Filee renderuje rysunek wektorowy do PNG z przezroczystością; skompresowane pliki SVGZ też działają.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `SVG po konwersji do PDF pozostaje wektorowy: linie i tekst są ostre przy każdym powiększeniu i w druku, a plik pozostaje mały. Przydatne przy wysyłaniu logo i diagramów do drukarni lub wstawianiu ich do dokumentów.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS może wyświetlić tylko interpreter PostScript; Filee używa do tego Ghostscriptu. PDF zachowuje grafikę wektorową, więc otworzy się wszędzie i nadal będzie ostro drukowany. Pliki PostScript (.ps) działają tak samo.`],

  // Conversion guides: PDF
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Każda strona staje się osobnym plikiem JPG, więc z 10-stronicowego PDF dostaniesz 10 obrazów. Przydatne w czatach, prezentacjach i postach w mediach społecznościowych, które przyjmują obrazy, ale nie PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG zachowuje wyraźny tekst i linie bez artefaktów JPG, co sprawdza się przy slajdach, diagramach, nutach i stronach, które chcesz opisać lub wstawić do prezentacji.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee zamienia PDF w dokument Word z prawdziwymi akapitami zamiast obrazów stron, więc możesz poprawić literówki lub ponownie wykorzystać tekst. Złożone układy mogą wymagać poprawek, a zeskanowany PDF zawierający tylko obrazy stron nie ma tekstu do wyodrębnienia.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee samo przechodzi drogę PDF → Word → EPUB, dzięki czemu tekst dopasowuje się do ekranu telefonu lub czytnika. Najlepiej działa z plikami PDF zawierającymi prawdziwy tekst. Nagłówki stają się zwykłymi akapitami, a zeskanowane strony nie mają tekstu do konwersji.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee przenosi tekst z PDF do dokumentu Word, zapisuje go jako HWPX, a ten z kolei jako HWP – wszystko wbudowanymi silnikami. Działa z plikami PDF zawierającymi prawdziwy tekst. Złożone układy mogą wymagać poprawek, a zeskanowane strony nie mają tekstu do wyodrębnienia.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee najpierw zamienia PDF w dokument Word, a potem w Markdown, zachowując akapity, nagłówki i pogrubienia tam, gdzie potrafi je rozróżnić. Przydatne do notatek, wiki lub wklejania tekstu do innych narzędzi. Zeskanowane strony nie mają tekstu do konwersji.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Koreańskie urzędy często wymagają dokumentów w formacie Hangul. Filee zamienia tekst z PDF w plik HWPX, który otworzysz i edytujesz w Hancom Hangul – sama konwersja nie wymaga Hancom Office; jeśli formularz wymaga starszego formatu, przekonwertuj go potem do HWP.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Przydatne, gdy PDF trzeba pokazać w PowerPoincie lub dodać do istniejącej prezentacji: każda strona staje się slajdem wyglądającym dokładnie jak PDF, a tekst strony czeka w notatkach prelegenta. Slajdy są obrazami, więc aby zmienić treść, przekonwertuj PDF do DOCX.`],

  // Conversion guides: documents
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Microsoft Word ani LibreOffice nie są potrzebne: Filee samo odczytuje DOCX i składa strony z nagłówkami, stopkami, tabelami i obrazami. Upuść kilka dokumentów na ustawienie Połącz PDF, aby złączyć je w jeden PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Stare dokumenty Word 97–2003 z archiwów, urzędowych formularzy lub dawnych systemów stają się plikami PDF, które otworzą się wszędzie. Ten sam silnik konwertuje też pliki ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord i Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Zapisuj e-maile jako PDF do archiwum, rozliczeń lub dokumentacji prawnej: PDF pokazuje nadawcę, odbiorców, datę, temat i treść, a otworzy się wszędzie bez programu pocztowego.`],

  // Conversion guides: HWP
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee renderuje strony HWP za pomocą rhwp, otwartoźródłowego silnika Hangul, więc ani Hancom Office, ani jego okno zatwierdzania nie są potrzebne. Przydatne przy wysyłaniu koreańskich dokumentów osobom, które nie mogą otworzyć HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Zamień dokument Hangul w plik Word, który mogą edytować współpracownicy za granicą. Tekst, akapity i tabele zostają przeniesione; układy z wieloma pływającymi obiektami warto szybko sprawdzić w Wordzie.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `HWPX, nowszy format Hangul oparty na XML, konwertuje się jak HWP: wbudowany silnik rhwp składa strony całkowicie offline. Przydatne do archiwizowania formularzy HWPX z instytucji publicznych jako PDF.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Niektóre systemy i nowsze procesy przyjmują tylko HWPX. Filee konwertuje binarny HWP do HWPX za pomocą rhwp, bez Hancom Office, i za jednym razem przerabia całą serię starych dokumentów.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Starsze wersje programu Hangul i niektóre portale do składania dokumentów wciąż oczekują .hwp. Filee konwertuje HWPX z powrotem do HWP za pomocą rhwp, więc nie musisz otwierać i ponownie zapisywać każdego pliku w programie Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Własny moduł zapisu HWPX w Filee przenosi układ z Worda: rozmiar strony i marginesy, nagłówki i stopki z numerami stron, tabele ze scalonymi komórkami, obramowaniem i cieniowaniem, pola tekstowe, kształty i obrazy. Każdy zapisany plik jest w testach sprawdzany trzema niezależnymi czytnikami HWPX.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Dla urzędów i formularzy, które wciąż wymagają .hwp. Filee zapisuje dokument Word jako HWPX własnym modułem, a następnie konwertuje go do HWP za pomocą rhwp – oba są wbudowane, więc do konwersji nie potrzeba Hancom Office.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Każda strona dokumentu Word staje się plikiem JPG (Filee najpierw składa dokument jako PDF) – przydatne do opublikowania strony w sieci lub wysłania szybkiego podglądu. Word nie jest potrzebny.`],

  // Conversion guides: spreadsheets
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Każdy widoczny arkusz staje się osobną sekcją, z formatami liczb, czcionkami, wypełnieniami, obramowaniami i scalonymi komórkami tak, jak pokazuje je Excel. Szerokie arkusze są skalowane do szerokości strony jak opcja Excela „Dopasuj wszystkie kolumny na jednej stronie”, a zablokowane wiersze nagłówka powtarzają się na każdej stronie.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV mieści jedną tabelę, więc Filee zapisuje jeden plik CSV na arkusz. Komórki są eksportowane jako wartości, gotowe do baz danych, skryptów i formularzy importu.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Skoroszyt XLSX może zawierać formatowanie, formuły i dodatkowe arkusze, których CSV nie obsługuje. Zaznacz wszystkie wyeksportowane pliki CSV i upuść je naraz, aby dostać jeden skoroszyt na plik – bez okna importu Excela.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Unowocześnij stare skoroszyty Excel 97–2003 bez Excela i LibreOffice: konwersja jest wbudowana. Pliki XLSX są zwykle mniejsze, nie mogą zawierać makr i otwierają się w każdym współczesnym arkuszu kalkulacyjnym.`],

  // Conversion guides: presentations
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Każdy slajd staje się jedną stroną PDF w rozmiarze slajdu – z tekstem, kształtami, obrazami, tabelami i projektem wzorca. Przydatne do rozdawania prezentacji lub przesyłania ich tam, gdzie pliki PowerPoint nie są akceptowane. Animacje i notatki prelegenta nie trafiają do PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Stare prezentacje PowerPoint 97–2003 stają się plikami PDF, które każdy może otworzyć, wydrukować lub przesłać. Prezentacje Keynote (.key), ODP i WPS (DPS) konwertują się tak samo.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Każdy slajd staje się plikiem JPG, gotowym do postów w mediach społecznościowych, miniatur, wiadomości na czacie lub edytora wideo. Jeśli na slajdach jest dużo drobnego tekstu, wybierz PNG.`],

  // Conversion guides: text
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Nagłówki, listy (także listy zadań), tabele, kod, cytaty, linki, obrazy, przypisy i wzory matematyczne są składane na stronach A4 – bez Pandoca, LaTeX-a i przeglądarki. Szybki sposób na udostępnienie notatek i plików README osobom, które nie czytają Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Wbudowane, bez Pandoca. Nagłówki, listy, tabele, linki i przypisy zostają przeniesione, więc możesz dalej edytować dokument i zmieniać jego style w Wordzie.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Zwykły tekst staje się schludnym PDF w formacie A4, z jednym akapitem na linię. Filee rozpoznaje UTF-8 i UTF-16, a także dawne koreańskie pliki tekstowe (CP949), więc stare logi i notatki nie zamieniają się w krzaki.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Zapisz stronę internetową lub raport HTML jako PDF, który wszędzie wygląda tak samo i nadaje się do archiwizacji lub druku. Filee konwertuje pliki .html zapisane na Twoim komputerze, a kilka z nich można połączyć w jeden PDF.`],

  // Conversion guides: e-books
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `PDF ma stały układ stron, co przydaje się do wydrukowania e-booka, czytania go na komputerze lub wysłania na urządzenie bez czytnika EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Przenieś starą bibliotekę Kindle/Mobipocket do EPUB, aby otwierała się w Apple Books, Google Play Books, Kobo i większości aplikacji do czytania. Ten kierunek jest wbudowany, więc Calibre nie jest potrzebny.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `Pliki MOBI i AZW3 zapisuje narzędzie do e-booków Calibre. Obecne Kindle przyjmują też EPUB przez Send to Kindle, więc MOBI przydaje się głównie na starszych urządzeniach i w starszych aplikacjach Kindle.`],

  // Conversion guides: video
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Zapisz dźwięk z wykładu, koncertu lub wywiadu jako MP3, który zagra wszędzie: w samochodzie, na starym odtwarzaczu czy w narzędziu do transkrypcji.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Filmy z iPhone’a i Maca to pliki MOV. Jako MP4 odtworzą się na telefonach z Androidem, telewizorach smart, w starszych aplikacjach Windows i w formularzach przesyłania, które odrzucają MOV. Obraz i dźwięk zwykle pasują do MP4 bez zmian, więc Filee tylko je przepakowuje: bez utraty jakości, z zachowaniem HDR, w kilka sekund. Ustawienie wstępne MP4 720p zmniejsza klipy 4K do udostępniania.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Nagrań MKV, np. z OBS, często nie da się zaimportować do edytorów wideo ani odtworzyć na telewizorze, a MP4 jest akceptowany niemal wszędzie. Konwersja odbywa się lokalnie, więc długich nagrań nigdy nie trzeba przesyłać.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Nagrania ekranu i filmy zapisane z przeglądarki to często WebM, z którym wiele edytorów wideo, starszych odtwarzaczy i komunikatorów słabo sobie radzi. MP4 odtwarza się niemal wszędzie, a całą serię klipów przekonwertujesz za jednym razem.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Zamień krótki klip w animowany GIF do czatu, dokumentacji lub zgłoszenia błędu. Niech będzie krótki: GIF zapisuje każdą klatkę jako obraz w 256 kolorach, więc długie filmy lub filmy w wysokiej rozdzielczości dają bardzo duże pliki.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Film upuszczony na JPG daje jeden nieruchomy obraz. Aby wybrać miniaturę lub przejrzeć klip klatka po klatce, użyj ustawienia wstępnego Wyodrębnij klatki (JPG): obrazy trafią do folderu obok filmu – każda klatka lub co N-ta. Film, z którego powstałoby ponad 100 000 obrazów albo który zapełniłby dysk, jest odrzucany przed rozpoczęciem.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Pliki AVI ze starych kamer i aparatów są duże i często używają kodeków, których telefony i telewizory już nie odtwarzają. MP4 z nowoczesną kompresją jest zwykle znacznie mniejszy i odtwarza się wszędzie.`],

  // Conversion guides: audio
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Nagranie WAV zajmuje około 10 MB na minutę; jako MP3 potrzebuje ułamka tego miejsca i nadal zagra na każdym urządzeniu.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Zachowaj bezstratną bibliotekę FLAC w domu, a kopie MP3 wgraj na telefon, pendrive do samochodu lub starszy odtwarzacz, który nie obsługuje FLAC. Całe albumy konwertują się za jednym razem.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Notatki głosowe z iPhone’a, pliki z iTunes bez DRM i wiele dyktafonów zapisuje M4A. MP3 przyjmie każdy odtwarzacz, radio samochodowe i formularz przesyłania.`],

  // Conversion guides: archives
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Przepakuj archiwa RAR do ZIP dla osób, formularzy przesyłania i systemów, które przyjmują tylko ZIP. WinRAR nie jest potrzebny ani do odczytu RAR, ani do zapisu ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z często kompresuje lepiej, ale ZIP otworzy się na każdym komputerze i telefonie bez dodatkowych programów. Konwertuj, gdy wysyłasz archiwum komuś, kto nie ma 7-Zip.`],

  // Conversion guides: CAD
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Wysyłaj rysunki klientom, ekipom na budowie lub drukarniom, które nie mają AutoCAD: PDF otworzy się na każdym komputerze i telefonie. Kilka rysunków można połączyć w jeden PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `Pliki DXF z programów CAD, zleceń cięcia laserowego lub wymiany projektów stają się plikami PDF, które każdy może otworzyć i wydrukować. Dostępne są też SVG i PNG, np. do podglądów w sieci.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF to format wymiany, który odczytują wycinarki laserowe, oprogramowanie CNC i większość programów CAD. Konwersja DWG do DXF pozwala otworzyć rysunki z AutoCAD w tych narzędziach, a w drugą stronę – z DXF do DWG – też działa.`],

  // Conversion guides: fonts
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Hostuj czcionkę na własnej stronie: WOFF2 to skompresowany format czcionek internetowych obsługiwany przez każdą nowoczesną przeglądarkę, zwykle o około 30% mniejszy niż WOFF. Sprawdź, czy licencja czcionki pozwala na osadzanie w sieci.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Niektóre starsze programy, plotery tnące, hafciarki i silniki gier przyjmują tylko czcionki TrueType. Przekonwertuj całą rodzinę czcionek OTF do TTF za jednym razem, bez edytora czcionek.`],

  // Conversion guides: tracing and SVG → CAD
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Do logo, podpisów i skanów użyj ustawienia Rysunek do SVG: tusz staje się jednym czarnym kształtem na przezroczystym tle. Wektoryzuj do SVG zachowuje do 64 kolorów – do ikon i ilustracji. Zdjęcia wychodzą jako płaskie plamy, więc wektoryzacja najlepiej sprawdza się przy rysunkach.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `JPG z logo lub zeskanowany szkic staje się plikiem SVG ostrym w każdym rozmiarze, gotowym do plotera tnącego, na stronę internetową lub do drukarni. Szum JPG zamienia się w drobinki, więc jeśli wynik wygląda na zaśmiecony, zmniejsz w ustawieniu wartość „Szczegóły”.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Wycinarki laserowe, oprogramowanie CNC i programy CAD odczytują DXF. Filee zapisuje kontury SVG w milimetrach, więc kształt o szerokości 100 mm pozostaje 100 mm. Krzywe stają się gęstymi poliliniami. Wypełnienia, obrazy i filtry są pomijane.`],

  // Conversion guides: e-mail
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `E-maile przeciągnięte z Outlooka to pliki MSG, które otwiera tylko Outlook. Jako PDF zachowują nadawcę, odbiorców, datę, temat i treść, a otworzą się wszędzie. Outlook nie jest potrzebny.`],

  // Conversion guides: data
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML łatwiej czytać i edytować ręcznie, dlatego używają go pliki konfiguracyjne. Klucze zachowują kolejność, a tekst, który przy ponownym odczycie stałby się liczbą lub wartością true/false, trafia w cudzysłów.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Zamień plik konfiguracyjny na JSON dla API, skryptu lub narzędzia, które czyta tylko JSON. Kotwice i aliasy są rozwijane, a plik z kilkoma dokumentami staje się jedną tablicą. Komentarze są pomijane, bo JSON ich nie obsługuje.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Lista rekordów w JSON staje się tabelą, którą otworzysz w Excelu: jeden wiersz na rekord, jedna kolumna na klucz. Obiekt opakowujący w rodzaju {"users": […]} jest rozpakowywany. Dane, które nie są tabelą, kończą się komunikatem zamiast uszkodzonego pliku.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Przenieś książkę adresową do Excela lub narzędzia do wysyłki maili: jeden wiersz na kontakt z imieniem i nazwiskiem, organizacją, e-mailem, telefonem, adresem i datą urodzin. Kontakty ze starych koreańskich telefonów w CP949 są odczytywane poprawnie.`],

  // Conversion guides: subtitles
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Odtwarzacze internetowe i platformy kursów online wymagają WebVTT. Czasy, podziały wierszy i kursywa zostają przeniesione, a żaden silnik nie jest potrzebny.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Wiele odtwarzaczy, telewizorów i edytorów nie odczytuje SMI, a stare koreańskie pliki SMI często wyświetlają się jako krzaki. Filee wykrywa CP949, wybiera język z największą liczbą linii i zapisuje czysty SRT w UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Gdy telewizor, telefon lub serwis wideo odrzuca stylizowane napisy ASS, zwykłe SRT zadziała. Pogrubienie, kursywa, podkreślenie i kolory zostają; pozycje, czcionki i efekty są pomijane.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Wyciągnij napisy z filmu, aby je edytować lub przetłumaczyć. Pierwsza tekstowa ścieżka napisów zostaje zapisana jako SRT; napisów graficznych (DVD, Blu-ray) nie da się zamienić na tekst. Wymaga darmowego silnika FFmpeg.`],

  // Conversion guides: 3D models
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Otwórz plik do druku w programie 3D, który woli OBJ. STL nie ma jednostek, więc Filee odczytuje go w milimetrach i zapisuje OBJ także w milimetrach, z osią Y skierowaną w górę, jak w większości programów 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Slicery do drukarek 3D przyjmują STL. Ściany dowolnego kształtu są dzielone na trójkąty, a oś Y skierowana w górę zamienia się na oś Z, więc stojący model stoi na stole drukarki. STL zapisuje tylko kształt, więc kolory i tekstury zostają w OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Przenieś model z sieci lub silnika gry do programu, który czyta OBJ. Plik .mtl i tekstury są zapisywane obok pliku .obj, więc trzymaj je razem.`],

  // FAQ
  [`Is Filee really free?`,
    `Czy Filee jest naprawdę darmowe?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Tak. Filee jest darmowe i otwartoźródłowe na licencji MIT: bez reklam, znaków wodnych, konta i okresu próbnego, bez własnych limitów liczby czy rozmiaru plików.`],
  [`Does it work offline? Are my files uploaded?`,
    `Czy działa offline? Czy moje pliki są gdzieś przesyłane?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Każda konwersja odbywa się na Twoim komputerze, a pliki nigdy nie są przesyłane. Internet służy tylko do pobrania opcjonalnego silnika lub sprawdzenia aktualizacji, więc poufne dokumenty, zdjęcia i nagrania zostają u Ciebie.`],
  [`Which file formats does Filee support?`,
    `Jakie formaty plików obsługuje Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee odczytuje {formatTotal|one:# format|few:# formaty|many:# formatów|other:# formatu} plików w {categoryCount|one:# kategorii|other:# kategoriach}: {categoryList}. {builtinTotal|one:# z nich działa|few:# z nich działają|other:# z nich działa} od razu po instalacji; pozostałe korzystają z darmowego opcjonalnego silnika. Katalog formatów wymienia każdy format i to, na co można go przekonwertować.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Czy potrzebuję Microsoft Office, Hancom Office lub LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF. Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Nie. Pliki Word, Excel i PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) oraz koreańskie dokumenty HWP/HWPX konwertują silniki wbudowane w Filee. Filee nie używa Office ani Hancom Office, nawet jeśli są zainstalowane; LibreOffice to tylko opcjonalny dodatek do pobrania w aplikacji, potrzebny przy starszych formatach, takich jak DOC, PPT, ODT i RTF. Wyjątkiem jest tekst wymagający kształtowania (arabski, hebrajski, pisma indyjskie, tajski i inne): pliki DOCX, TXT, Markdown, HTML, XLSX, PPTX i HWPX z takim tekstem trafiają do PDF i obrazów przez opcjonalny silnik LibreOffice. Bez LibreOffice konwersja takiego pliku kończy się komunikatem podającym nazwę pisma, zamiast dawać uszkodzony plik PDF.`],
  [`What are the optional engines?`,
    `Czym są opcjonalne silniki?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Duże silniki nie są częścią instalatora. Zaznacz je na stronie silników w instalatorze albo pobierz w Filee, kiedy będą potrzebne: {engineDetails}. Są zapisywane we własnym folderze Filee i można je w każdej chwili usunąć, a aplikacja pokazuje ich wersje, prędkość pobierania i pozostały czas. Jeśli FFmpeg, calibre, Pandoc, Ghostscript lub LibreOffice jest już na Twoim komputerze (w PATH, także przez Scoop, lub w Program Files), Filee go używa i pomija pobieranie, a gdy ta kopia jest starsza niż wersja, z którą Filee jest testowane, informuje o tym. Konkretną kopię wskażesz w Ustawienia → Silniki → Użyj mojej kopii.`],
  [`Does installing Filee need administrator rights?`,
    `Czy instalacja Filee wymaga uprawnień administratora?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Tylko raz, podczas instalacji. Instalator umieszcza Filee w Program Files dla wszystkich użytkowników, a w Windows 11 dodaje „Konwertuj w Filee” na górę menu Eksploratora plików. Samo Filee działa potem z uprawnieniami zwykłego użytkownika. Aby zainstalować po cichu, uruchom instalator z parametrami /VERYSILENT /SUPPRESSMSGBOXES. Jeśli nie możesz instalować programów, użyj przenośnego pliku ZIP: rozpakuj go w dowolnym miejscu i uruchom Filee.exe.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `Filee nie uruchamia się w Windows 10: nie ma okna ani błędu. Co zrobić?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Dzieje się tak w Windows 10, który od dawna nie był aktualizowany, na komputerze z procesorem obsługującym wymuszaną sprzętowo ochronę stosu (CET). Windows włącza tę ochronę, ale brakuje mu elementu potrzebnego platformie .NET, więc Filee i jego instalator od razu się zamykają, bez okna i bez komunikatu. Pomaga zainstalowanie dostępnych aktualizacji Windows (najnowszej aktualizacji zbiorczej). Jeśli aktualizacja nie jest możliwa, zwykle wystarczy wyłączyć ochronę tylko dla Filee: w PowerShell uruchomionym jako administrator wykonaj Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, a potem to samo dla filee-cli.exe i dla nazwy pliku instalatora (albo użyj przenośnego pliku ZIP). Aby to cofnąć, usuń te wpisy w Zabezpieczenia Windows → Kontrola aplikacji i przeglądarki → Ustawienia ochrony przed lukami w zabezpieczeniach → Ustawienia programu.`],
  [`Can I convert many files at once?`,
    `Czy mogę konwertować wiele plików naraz?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Tak. Zaznacz dowolnie wiele plików i upuść je jednym ruchem: Filee konwertuje je równolegle, błąd jednego pliku nie zatrzymuje pozostałych, a ustawienia wstępne mogą połączyć wszystko w jeden PDF lub spakować w jeden ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Czy mogę konwertować z menu kontekstowego Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Tak. Kliknij pliki prawym przyciskiem w Eksploratorze plików i wybierz „Konwertuj w Filee”. W Windows 11 możesz też umieścić tę pozycję w głównym menu, bez „Pokaż więcej opcji”: raz kliknij „Dodaj do głównego menu” w Ustawienia → Ogólne i zatwierdź monit administratora. Działają też menu Wyślij do, skrót klawiszowy i strefa upuszczania w oknie głównym.`],
  [`Can Filee convert from the command line or automatically?`,
    `Czy Filee może konwertować z wiersza poleceń lub automatycznie?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Tak. Instalator może dodać polecenie filee do PATH: filee convert *.heic --to jpg konwertuje pliki, symbole wieloznaczne i foldery z użyciem Twoich ustawień wstępnych, wypisuje JSON dla skryptów i zwraca kody wyjścia. Obserwowane foldery automatycznie konwertują pliki, które do nich trafiają, i mogą odkładać oryginały na bok. Skonfigurujesz je na stronie Obserwowane foldery w aplikacji lub poleceniem filee watch w terminalu.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `Jak przekonwertować plik, np. HEIC do JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Zaznacz pliki w Eksploratorze plików, przytrzymaj Ctrl (lub wybrany przez siebie klawisz) i przeciągnij je. Przy kursorze otworzy się pierścień formatów: upuść pliki na JPG, a nowe pliki pojawią się obok oryginałów. Dla najczęstszych konwersji są poradniki krok po kroku.`],
  [`Why use Filee instead of an online converter?`,
    `Dlaczego Filee zamiast konwertera online?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Konwertery online przesyłają Twoje pliki na cudzy serwer, często ograniczają rozmiar i liczbę plików i zależą od szybkiego łącza. Filee konwertuje na Twoim komputerze: prywatne pliki pozostają prywatne, duże filmy i setki plików to żaden problem, a wszystko działa bez internetu, za darmo i bez reklam.`],
  [`Which operating systems are supported?`,
    `Jakie systemy operacyjne są obsługiwane?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Pełne wersje są dla Windows 10 i 11 (64-bitowych) oraz Linuksa (x64 i ARM64, Ubuntu 22.04 lub nowszy). W Linuksie gest przeciągania wymaga sesji X11; w KDE Plasma z Waylandem jest eksperymentalny, a w innych środowiskach z Waylandem działają strefa upuszczania i menu kontekstowe menedżera plików. macOS 13 lub nowszy (Apple Silicon i Intel) to wersja zapoznawcza: aplikacja nie jest jeszcze notaryzowana, więc macOS poprosi o jednorazowe zezwolenie w sekcji Prywatność i ochrona. Wybierz swój system w sekcji pobierania.`],
]);
